% Preallocate arrays for results
displacement = zeros(size(t));
velocity = zeros(size(t));

% Set initial conditions
displacement(1) = initial_displacement;
velocity(1) = initial_velocity;

% Time integration using Euler's method
for i = 1:length(t)-1
    % Calculate acceleration
    acceleration = (-SPRING_CONSTANT * displacement(i) - DAMPING_COEFFICIENT * velocity(i)) / MASS;

    % Update velocity and displacement
    velocity(i+1) = velocity(i) + acceleration * dt;
    displacement(i+1) = displacement(i) + velocity(i) * dt;
end

% Plot results
figure;
subplot(2,1,1);
plot(t, displacement, 'LineWidth', 1.5);
xlabel('Time (s)');
ylabel('Displacement (m)');
title('Displacement vs. Time');
grid on;

subplot(2,1,2);
plot(t, velocity, 'LineWidth', 1.5);
